() => {
  const textarea = document.querySelector('textarea');
  if (!textarea) return 'no textarea found';
  return {
    id: textarea.id,
    className: textarea.className,
    placeholder: textarea.placeholder,
    parentTag: textarea.parentElement?.tagName,
    parentClass: textarea.parentElement?.className
  };
}

() => {
  // Check if React fiber is on the textarea or its parents
  const textarea = document.querySelector('textarea');
  let el = textarea;
  let reactKeys = [];
  while (el) {
    const keys = Object.keys(el).filter(k => k.startsWith('__react'));
    if (keys.length > 0) {
      reactKeys.push({ tag: el.tagName, class: el.className, keys });
    }
    el = el.parentElement;
  }
  return reactKeys;
}

() => {
  // Get component hierarchy from React fiber
  const textarea = document.querySelector('textarea');
  const fiberKey = Object.keys(textarea).find(k => k.startsWith('__reactFiber'));
  let fiber = textarea[fiberKey];
  let components = [];
  while (fiber) {
    if (fiber.type && typeof fiber.type === 'function') {
      components.push({
        name: fiber.type.displayName || fiber.type.name || 'Anonymous',
        hasState: fiber.memoizedState !== null,
        stateCount: (() => {
          let count = 0;
          let s = fiber.memoizedState;
          while (s) { count++; s = s.next; }
          return count;
        })()
      });
    }
    fiber = fiber.return;
  }
  return components;
}

() => {
  // Get all component tree from AppProvider down
  const root = document.querySelector('[id="root"]') || document.querySelector('div');
  const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber'));
  let fiber = root[containerKey];

  // Walk fiber tree to find all components
  function walkFiber(fiber, depth = 0) {
    let results = [];
    if (!fiber) return results;
    if (fiber.type && typeof fiber.type === 'function') {
      const name = fiber.type.displayName || fiber.type.name || 'Anonymous';
      const hasMemo = fiber.type.$$typeof?.toString() === 'Symbol(react.memo)';
      results.push({
        name,
        depth,
        hasMemo,
        stateCount: (() => {
          let count = 0;
          let s = fiber.memoizedState;
          while (s) { count++; s = s.next; }
          return count;
        })()
      });
    }
    // Child
    if (fiber.child) {
      results = results.concat(walkFiber(fiber.child, depth + 1));
    }
    // Sibling
    if (fiber.sibling) {
      results = results.concat(walkFiber(fiber.sibling, depth));
    }
    return results;
  }

  return walkFiber(fiber);
}

() => {
  const root = document.querySelector('[id="root"]') || document.querySelector('div');
  const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber'));
  let fiber = root[containerKey];

  let componentCounts = {};
  let totalComponents = 0;

  function walkFiber(fiber) {
    if (!fiber) return;
    if (fiber.type && typeof fiber.type === 'function') {
      const name = fiber.type.displayName || fiber.type.name || 'Anonymous';
      componentCounts[name] = (componentCounts[name] || 0) + 1;
      totalComponents++;
    }
    if (fiber.child) walkFiber(fiber.child);
    if (fiber.sibling) walkFiber(fiber.sibling);
  }

  walkFiber(fiber);
  return { totalComponents, componentCounts };
}

() => {
  // Check AppProvider's state hooks to see if notes is stored there
  const root = document.querySelector('[id="root"]') || document.querySelector('div');
  const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber'));
  let fiber = root[containerKey];

  function findFiber(fiber, name) {
    if (!fiber) return null;
    if (fiber.type && (fiber.type.displayName === name || fiber.type.name === name)) return fiber;
    let result = findFiber(fiber.child, name);
    if (result) return result;
    return findFiber(fiber.sibling, name);
  }

  const appProvider = findFiber(fiber, 'AppProvider');
  if (!appProvider) return 'AppProvider not found';

  // Walk state hooks
  let states = [];
  let hook = appProvider.memoizedState;
  let i = 0;
  while (hook) {
    let val = hook.memoizedState;
    let type = typeof val;
    let preview = '';
    if (type === 'string') preview = val.substring(0, 100);
    else if (Array.isArray(val)) preview = `Array(${val.length})`;
    else if (type === 'object' && val !== null) preview = JSON.stringify(val).substring(0, 100);
    else preview = String(val);

    states.push({ hookIndex: i, type, preview });
    hook = hook.next;
    i++;
  }
  return states;
}

() => {
  const root = document.querySelector('[id="root"]') || document.querySelector('div');
  const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer') || k.startsWith('__reactFiber'));
  let fiber = root[containerKey];

  function findFiber(fiber, name) {
    if (!fiber) return null;
    if (fiber.type && (fiber.type.displayName === name || fiber.type.name === name)) return fiber;
    let result = findFiber(fiber.child, name);
    if (result) return result;
    return findFiber(fiber.sibling, name);
  }

  const appProvider = findFiber(fiber, 'AppProvider');
  if (!appProvider) return 'AppProvider not found';

  let states = [];
  let hook = appProvider.memoizedState;
  let i = 0;
  while (hook && i < 10) {
    let val = hook.memoizedState;
    let type = typeof val;
    let preview = '';
    try {
      if (type === 'string') preview = val.substring(0, 100);
      else if (Array.isArray(val)) preview = `Array(${val.length})`;
      else if (type === 'function') preview = 'function';
      else if (type === 'object' && val !== null) {
        // Try to get top-level keys only
        let keys = Object.keys(val);
        preview = `Object{${keys.join(',')}}`;
      }
      else preview = String(val);
    } catch(e) {
      preview = `Error: ${e.message}`;
    }

    states.push({ hookIndex: i, type, preview });
    hook = hook.next;
    i++;
  }
  return states;
}

